    key.clear()
class Indexer:
    def __getitem__(self, key): clear(key)
    def __setitem__(self, key, value): clear(key)
    def __delitem__(self, key): clear(key)
INDEXER = Indexer()
TESTS = ["owned"]
KEY = (TESTS,)
INDEXER[TESTS]

